        }
        const existingDirectory = db.prepare('SELECT id FROM rpc_commerce_preparations WHERE directory=?').get(directory);
        if (existingDirectory) throw new WorkspaceError('RPC_COMMERCE_ALREADY_RETAINED', 409,
